package local.skyfamily;
import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
final class PdfMarkup extends FrameLayout {
 final PdfPane pane;final HashMap<Integer,StudyInk.Model> pages=new HashMap<>();final HashSet<Integer> loaded=new HashSet<>(),broken=new HashSet<>();Bitmap last;int displayed=-1,tool=1;boolean touching=false;
 PdfMarkup(PdfPane value){super(value.host);pane=value;setWillNotDraw(false);addView(value.image,new FrameLayout.LayoutParams(-1,-1));setContentDescription("PDF annotation layer saved on this device. Pen and Highlight draw; Pan navigates. Original PDF is unchanged.");}
 RectF bounds(){Bitmap image=pane.image.bitmap;if(image==null)return new RectF();float factor=Math.min(getWidth()/(float)image.getWidth(),getHeight()/(float)image.getHeight())*pane.image.zoom;float w=image.getWidth()*factor,h=image.getHeight()*factor;return new RectF((getWidth()-w)/2+pane.image.panX,(getHeight()-h)/2+pane.image.panY,(getWidth()+w)/2+pane.image.panX,(getHeight()+h)/2+pane.image.panY);}
 boolean ready(){if(pane.closed||pane.image.bitmap==null||pane.status.getText().toString().startsWith("Rendering"))return false;if(last!=pane.image.bitmap){last=pane.image.bitmap;displayed=pane.page;}return displayed==pane.page;}
 String key(){return pane.key+".annotations."+displayed;}
 StudyInk.Model model(){if(!loaded.contains(displayed)){if(loaded.size()>=100){pane.host.toast("Annotation session limit reached; reopen the PDF");return null;}loaded.add(displayed);try{pages.put(displayed,StudyInk.Model.parse(pane.host.get(key())));}catch(Exception error){if(pane.host.get(key()).isEmpty())pages.put(displayed,new StudyInk.Model());else{broken.add(displayed);pane.host.toast("Cannot load saved annotations safely; this page is read-only");}}}return pages.get(displayed);}
 void save(){StudyInk.Model model=pages.get(displayed);if(model==null||broken.contains(displayed))return;try{if(!pane.host.prefs.edit().putString(key(),model.json()).commit())throw new java.io.IOException();}catch(Exception error){pane.host.toast("PDF annotations NOT SAVED / keep PDF open and check storage");}}
 protected void dispatchDraw(Canvas canvas){super.dispatchDraw(canvas);if(ready()){StudyInk.Model model=model();if(model!=null)model.draw(canvas,bounds());}}
 public boolean onInterceptTouchEvent(MotionEvent event){return tool!=0;}
 public boolean onTouchEvent(MotionEvent event){if(tool==0)return false;if(!ready())return true;int action=event.getActionMasked();StudyInk.Model model=model();if(model==null||broken.contains(displayed))return true;if(event.getPointerCount()>1){model.cancel();touching=false;invalidate();return true;}RectF box=bounds();if(box.width()<=0||box.height()<=0)return true;if(action==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);if(!box.contains(event.getX(),event.getY()))return true;touching=model.begin((event.getX()-box.left)/box.width(),(event.getY()-box.top)/box.height(),tool==2?0x66ffcf33:0xff245cb3,tool==2?22:4);if(!touching)pane.host.toast("Ink limit reached for this page");}else if(action==MotionEvent.ACTION_MOVE&&touching){for(int i=0;i<event.getHistorySize();i++)model.add((event.getHistoricalX(i)-box.left)/box.width(),(event.getHistoricalY(i)-box.top)/box.height());model.add((event.getX()-box.left)/box.width(),(event.getY()-box.top)/box.height());}else if(action==MotionEvent.ACTION_UP){model.end();if(touching)save();touching=false;getParent().requestDisallowInterceptTouchEvent(false);performClick();}else if(action==MotionEvent.ACTION_CANCEL){model.cancel();touching=false;getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}
 public boolean performClick(){super.performClick();return true;}void undo(){if(!ready())return;StudyInk.Model model=model();if(model!=null&&!broken.contains(displayed)){model.undo();save();invalidate();}}void clearPage(){if(!ready()||broken.contains(displayed))return;StudyInk.Model model=model();if(model!=null){model.clear();save();invalidate();}}
}
